diff --git a/repro/no-lonely-if-19033.js b/repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..53918dc
--- /dev/null
+++ b/repro/no-lonely-if-19033.js
@@ -0,0 +1,26 @@
+"use strict";
+// Repro: no-lonely-if autofix changes which `if` the outer `else` binds to.
+const assert = require("node:assert");
+const { Linter } = require(process.env.ESLINT_PATH || "../lib/api");
+console.log("eslint", require(require("node:path").join(require.resolve(process.env.ESLINT_PATH || "../lib/api"), "../../package.json")).version, "from", require.resolve(process.env.ESLINT_PATH || "../lib/api"));
+
+const code = `if (true)
+	if (false) {}
+	else { if (false) {} }
+else throw Error('This \`else\` should have been unreachable!');
+`;
+
+const linter = new Linter();
+const config = { rules: { "no-lonely-if": "error" } };
+const messages = linter.verify(code, config);
+const { output } = linter.verifyAndFix(code, config);
+
+console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.message}`));
+console.log("--- fixed output ---\n" + output);
+
+const run = src => { try { new Function(src)(); return "ok"; } catch (e) { return `threw: ${e.message}`; } };
+console.log("original runs:", run(code));
+console.log("fixed runs:   ", run(output));
+
+assert.strictEqual(run(output), run(code), "BUG: autofix changed runtime behavior (outer else rebound to inner if)");
+console.log("PASS: fix preserved semantics");
